 "content": "def transform(grid):
    # On the short colored bar at bottom, recolor the right half to 1.
    out = [row[:] for row in grid]
    for r, row in enumerate(out):
        color = next((v for v in row if v not in (0, 1)), None)
        if color is None:
            continue
        # The bar is the unique row containing a partial run, adjacent to full same-color bar.
        indices = [i for i, v in enumerate(row) if v == color]
        if len(indices) < len(row):
            for c in indices:
                if c >= len(row)//2:
                    out[r][c] = 1
    return out
